#!/usr/bin/env python3
"""Compute the shear generated by the canonical A2 Cartan covector."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=ROOT/'research/benincasa/results'
prev=json.loads((R/'cosmology_A2_root_covector_shear_pairing.json').read_text());gate=json.loads((R/'cosmology_e6_rank12_triangular_transport_gate.json').read_text());assert prev['passed']
G=((2,-1),(-1,2));r=(0,-1);lam=(1,-2) # r^T G
Q=((0,-1),(1,-1));Qi=((-1,1),(-1,0));I=((1,0),(0,1))
def mm(A,B):return tuple(tuple(sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))) for i in range(len(A)))
def mv(A,v):return tuple(sum(A[i][j]*v[j] for j in range(len(v))) for i in range(len(A)))
def op(v,l):return tuple(tuple(v[i]*l[j] for j in range(2)) for i in range(2))
def add(*Ms):return tuple(tuple(sum(M[i][j] for M in Ms) for j in range(2)) for i in range(2))
T=op(r,lam);assert mm(T,Q)!=mm(Q,T)
terms=[]
for q,qi in ((I,I),(Q,Qi),(mm(Q,Q),mm(Qi,Qi))):terms.append(mm(op(mv(q,r),lam),qi))
S=add(*terms);assert S==((3,0),(0,3));normalized=tuple(tuple(x//3 for x in row) for row in S);assert normalized==I
out={'schema':'marici.benincasa.cosmology-A2-Cartan-covector-shear.v1','Cartan_Gram':[list(x) for x in G],'root_coordinates':list(r),'Cartan_covector':list(lam),'single_root_tensor':[list(x) for x in T],'single_root_tensor_cyclic':False,'orbit_sum':[list(x) for x in S],'orbit_sum_divisible_by_three':True,'normalized_orbit_sum':[list(x) for x in normalized],'normalized_shear_centralizer_coordinates':[1,0],'normalized_shear_primitive':True,'normalized_shear_occurrence_sensitive':False,'dichotomy':'the single tensor remembers the dlog root but breaks C3; the normalized orbit sum is C3-equivariant identity but forgets the root','required_rank12_shear':gate['missing']['off_diagonal_shear'],'rank12_shear_selected':False,'next_test':'test whether the normalized identity shear satisfies the missing q0 and connector naturality equations or is only a canonical graded endomorphism','passed':True};(R/'cosmology_A2_Cartan_covector_shear.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
